Ul(children=[Li(children=[P(children=[B(children=[Text(body=立即返回, children=[], params={})], params={}), Text(body=: 优先处理已到达的数据, 而不是等待数据流., children=[], params={})], params={})], params={}), Li(children=[P(children=[B(children=[Text(body=返回值, children=[], params={})], params={}), Text(body=: , children=[], params={}), CodeInline(children=[Text(body=Deferred, children=[], params={})], params={}), Text(body= 的结果是实际读取的字节数., children=[], params={})], params={})], params={}), Li(children=[P(children=[B(children=[Text(body=>, children=[], params={content-type=html}), Text(body= 0, children=[], params={})], params={}), Text(body=: 成功读取的字节数., children=[], params={})], params={})], params={}), Li(children=[P(children=[B(children=[Text(body=-1, children=[], params={})], params={}), Text(body=: 通道已关闭, 并且没有更多数据可读 (已到达流的末尾)., children=[], params={})], params={})], params={})], params={})

@param scope 执行异步读取操作的协程作用域.
@param buffer 用于接收读取数据的目标字节数组.
